ALTER TABLE run_daily_exceptions ADD COLUMN reader_option TEXT NOT NULL DEFAULT 'deepseek' CHECK(reader_option IN ('deepseek','deepseek_low'));
DROP TRIGGER run_daily_exception_enroll;
CREATE TRIGGER run_daily_exception_enroll BEFORE INSERT ON run_daily_exceptions WHEN NOT EXISTS(SELECT 1 FROM runs r JOIN quotes q ON q.id=r.quote_id JOIN controls k ON k.id=1 WHERE r.id=NEW.run_id AND r.quote_id=NEW.quote_id AND r.actor=NEW.actor AND q.actor=NEW.actor AND r.created_at<=NEW.granted_at AND q.created_at<=NEW.granted_at AND r.status='uploading' AND r.mode='interactive' AND k.kill=0 AND json_extract(r.pack_json,'$.pins.reader.id')=NEW.model_id AND json_extract(r.pack_json,'$.selectedReaderModel')=NEW.reader_option AND (NEW.reader_option='deepseek' OR (json_extract(r.pack_json,'$.settings.readerEffort')='low' AND json_extract(r.pack_json,'$.settings.readerMaxOutputTokens')=16384)) AND json_extract(r.pack_json,'$.settings.inferenceWindow.startAt')=NEW.start_at AND json_extract(r.pack_json,'$.settings.inferenceWindow.endAt')=NEW.end_at AND json_extract(r.budget_json,'$.mode')='unlimited' AND json_extract(r.budget_json,'$.actor')=NEW.actor AND json_type(r.budget_json,'$.unlimitedAcknowledged')='true' AND json_type(r.budget_json,'$.limits.blended')='null' AND json_type(r.budget_json,'$.limits.openai')='null' AND json_type(r.budget_json,'$.limits.typesafe')='null' AND NEW.start_at<=r.created_at AND r.created_at<NEW.end_at AND json_extract(r.pack_json,'$.settings.usageLimits.deepseekDailyNano') IS NOT NULL AND r.expected_count=json_array_length(NEW.fingerprints_json) AND r.expected_count=(SELECT COUNT(*) FROM quote_documents d WHERE d.quote_id=q.id) AND NOT EXISTS(SELECT 1 FROM json_each(NEW.fingerprints_json) j LEFT JOIN quote_documents d ON d.quote_id=q.id AND d.ordinal=j.key+1 WHERE j.type!='text' OR length(j.value)!=64 OR j.value GLOB '*[^0-9a-f]*' OR d.fingerprint IS NOT j.value) AND NOT EXISTS(SELECT 1 FROM documents x WHERE x.run_id=r.id) AND NOT EXISTS(SELECT 1 FROM checkpoints c WHERE c.run_id=r.id) AND NOT EXISTS(SELECT 1 FROM vendor_calls v WHERE v.run_id=r.id) AND NOT EXISTS(SELECT 1 FROM workflow_dispatch_admissions a WHERE a.run_id=r.id) AND NOT EXISTS(SELECT 1 FROM daily_usage_reservations h WHERE h.run_id=r.id)) OR EXISTS(SELECT 1 FROM run_daily_exceptions old JOIN runs prior_run ON prior_run.id=old.run_id JOIN json_each(old.fingerprints_json) prev JOIN json_each(NEW.fingerprints_json) next ON next.value=prev.value WHERE (old.reader_option=NEW.reader_option OR prior_run.status NOT IN ('complete','halted','closed') OR NEW.reader_option!='deepseek_low') AND old.actor=NEW.actor AND old.provider=NEW.provider AND old.model_id=NEW.model_id AND old.start_at<NEW.end_at AND NEW.start_at<old.end_at) BEGIN SELECT RAISE(ABORT,'The run cannot be enrolled for this provider allowance.'); END;
